export function StagLogo({
  size = 'md',
  variant = 'color',
  className,
  alt = '',
}: StagLogoProps) {
  const { dimension, class: sizeClass } = SIZES[size]

  if (variant === 'monochrome') {
    return (
      <svg
        viewBox="0 0 1024 1024"
        fill="none"
        role="img"
        aria-label={alt || undefined}
        aria-hidden={alt ? undefined : true}
        className={cn(sizeClass, 'shrink-0 text-brand select-none', className)}
      >
        <g transform="translate(0, 1024) scale(0.1, -0.1)">
          <path d={MARK_PATH} fill="currentColor" />
        </g>
      </svg>
    )
  }

  return (
    <img
      src="/media/brand/mccor-stag-logo.svg"
      alt={alt}
      width={dimension}
      height={dimension}
      decoding="async"
      className={cn(sizeClass, 'shrink-0 select-none', className)}
    />
  )
}
